head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/elw_recv_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/pre_newlisting.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/pf_listinvstg.js");
scwin.vScrenID = "ULDSTF09330.xml";
scwin.procJob = "";
scwin.pUsrTpCd = js_usr_tp_cd;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
}; //사용자구분코드	

scwin.fn_list_sync = function() {
    var url;

    //이후 영업 상장일
    url = "/ElwListedReceive.do?method=getElwListingListDd&inputMessageId=ELW_LISTING_TR_SEND_LOG_INOUT";
    url += "&TASK_DD=" + $c.stf.getObjectValue(edt_TASK_DD);
    dts_Get_ListDD.DataID = encodeURI(url);
    dts_Get_ListDD.Reset();

    //마감정보
    url = "/pf/PfLstinvstg.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=selectManagement&inputMessageId=PF_CLSBZ_LOG_INOUT";
    url += "&DIV_IDX=" + DIV_R_LISTING_PF_CLSBZ; //2
    url += "&TASK_DD=" + $c.stf.getObjectValue(edt_TASK_DD);
    dts_Item.DataID = encodeURI(url);
    dts_Item.Reset();

    //마감처리
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        //신규상장
        url = "/pf/PfLstinvstg.do";
        url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=selectManagement&inputMessageId=PF_NEWLISTING_INOUT";
        url += "&DIV_IDX=" + DIV_L_LISTING_PF_DETAIL; //3
        url += "&LIST_DD=" + $c.stf.getObjectValue(edt_LIST_DD);
        dts_New_Proc.DataID = encodeURI(url);
        dts_New_Proc.Reset();
        $c.cm.ShowWin(grd_New_Proc);

        //마감처리내역

    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        //마감처리내역
        url = "/pf/PfLstinvstg.do";
        url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=selectManagement&inputMessageId=PF_NEWLISTING_INOUT";
        url += "&DIV_IDX=" + DIV_L_LISTING_PF_SEND; //4
        url += "&TASK_DD=" + $c.stf.getObjectValue(edt_TASK_DD);
        dts_New_Search.DataID = encodeURI(url);
        dts_New_Search.Reset();
        $c.cm.ShowWin(grd_New_Search);
    }
};
scwin.fn_trSetHeader = function() {
    dts_Cls.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=PF_CLSBZ_LOG_INOUT";
    dts_Cls.reset();
    dts_Cls.insertRow();
};


//마감처리
scwin.fn_trsend = function() {
    scwin.procJob = "마감처리";
    res = window.confirm("[마감] 처리 하겠습니까?");
    if (res) {
        scwin.fn_trSetHeader();
        dts_Cls.setCellData(1, "TASK_DD", $c.stf.getObjectValue(edt_TASK_DD));
        dts_Cls.setCellData(1, "LIST_DD", $c.stf.getObjectValue(edt_LIST_DD));
        dts_Cls.setCellData(1, "APPROV_EMP_NO", js_emp_no);
        trs_Save.Action = "/pf/PfLstinvstg.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02 + "&method=savePFRevwProcs";
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInput=dts_Cls)";
        trs_Save.Parameters = "TRS_IDX=" + TR_JOB_INSERT + ",TASK_DD=" + $c.stf.getObjectValue(edt_TASK_DD);
        trs_Save.Post();
    }
};



//재마감
scwin.fn_re_trsend = function() {
    scwin.procJob = "재마감처리";
    var res = window.confirm("[재마감] 처리 하겠습니까?");
    if (res) {
        scwin.fn_trSetHeader();
        dts_Cls.setCellData(1, "TASK_DD", $c.stf.getObjectValue(edt_TASK_DD));
        dts_Cls.setCellData(1, "LIST_DD", $c.stf.getObjectValue(edt_LIST_DD));
        dts_Cls.setCellData(1, "APPROV_EMP_NO", js_emp_no);
        trs_Save.Action = "/pf/PfLstinvstg.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04 + "&method=savePFRevwProcs";
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInput=dts_Cls)";
        trs_Save.Parameters = "TRS_IDX=" + TR_JOB_DELETE + ",TASK_DD=" + $c.stf.getObjectValue(edt_TASK_DD);
        trs_Save.Post();
    }
};



// Button 
scwin.buttonTrSend = function() {
    //마감 Button 
    if ($c.stf.getObjectValue(txb_BZ_CLS_TM) == "") {
        btn_TrSend.setDisabled(false);
        btn_TrSend.src = "../img/btn_ClsPrc.gif";
    } else {
        btn_TrSend.setDisabled(true);
        btn_TrSend.src = "../img/btn_ClsPrc_d.gif";
    }

    //재마감 Button 
    if (scwin.pUsrTpCd == "1") {
        //운영자
        btn_ReTrSend.setDisabled(false);
        $c.stf.showObj(btn_ReTrSend, true);
    } else {
        btn_ReTrSend.setDisabled(true);
        $c.stf.showObj(btn_ReTrSend, false);
    }
};
scwin.fn_ExcelDown = function() {
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        $c.data.downloadGridViewExcel(grd_New_Proc, "상장형 수익증권 신규상장 마감처리목록", "", "8");
    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        $c.data.downloadGridViewExcel(grd_New_Search, "상장형 수익증권 신규상장 송신목록", "", "8");
    }
};
scwin.MaxTab_01_OnSelChanged = function(nIndex) {
    if (nIndex == "1") {
        edt_TASK_DD.setReadOnly(true);
        img_TASK_DD.setDisabled(true);
        edt_TASK_DD.ReadOnlyBackColor = "#b9d4f7";
        edt_TASK_DD.setValue($c.ut.cGetToday("yyyymmdd"));
    } else if (nIndex == "2") {
        edt_TASK_DD.setReadOnly(false);
        img_TASK_DD.setDisabled(false);
    }
    scwin.fn_list_sync();
};
scwin.btn_Search_onclick = function() {
    scwin.fn_list_sync();
};
scwin.btn_ProcClose_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.btn_ProcExcel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    scwin.fn_ExcelDown();
};
scwin.btn_SearchExcel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    scwin.fn_ExcelDown();
};
scwin.img_TASK_DD_onclick = function() {
    popUpCalendar2(edt_TASK_DD);
};
scwin.dts_Get_ListDD_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002", ""));
};
scwin.dts_Item_OnLoadError = function() {
    $c.stf.alert_error(dts_Item);
};
scwin.dts_New_Search_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002", ""));
};
scwin.dts_New_Search_OnLoadCompleted = function(rowcount) {
    edt_New_Search_TotalCnt.setValue("총 " + dts_New_Search.getTotalRow() + " 건");
    $c.cm.CloseWin(rowcount, grd_New_Search);
};
scwin.trs_Save_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", scwin.procJob));
    $c.stf.alert_error(trs_Save);
};
scwin.trs_Save_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0001", scwin.procJob));
    scwin.fn_list_sync();
};
scwin.btn_ProcClose_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.btn_SearchClose_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.btn_TrSend_onclick = function() {
    scwin.fn_trsend();
};
scwin.btn_ReTrSend_onclick = function() {
    scwin.fn_re_trsend();
};
scwin.dts_New_Proc_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002", ""));
};
scwin.dts_New_Proc_OnLoadCompleted = function(rowcount) {
    edt_New_Proc_TotalCnt.setValue("총 " + dts_New_Proc.getTotalRow() + " 건");
    $c.cm.CloseWin(rowcount, grd_New_Proc);
    scwin.buttonTrSend();
};
scwin.gform_onload = function() {
    //담당자 버튼
    btn_TrSend.setDisabled(true);

    //마감일
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    $c.stf.setObjectValue(edt_TASK_DD, vCurDate);
    MaxTab_01.setSelectedTabIndex(1);
    $c.cm.PanelToGroupBox(panel_Top);

    //조회
    scwin.fn_list_sync();
};
